		void InitialiseCodes()
		{
			var isoGroupTypes = typeof(ISOTypeGroup).GetFields();
			foreach (var isoGroupType in isoGroupTypes)
			{
				var code = isoGroupType.Name.Substring(fieldPrefix.Length);
				var description = (ResourceString)isoGroupType.GetValue(null);

				AddPair(code, description);
			}
		}

		public bool IsISOTypeGroup(string proposedCode)
